"""Cloud process adapter: stop new claims, finish current work, resume on lease expiry.

No AI repository changes. Wrap the existing runner_loop with its supported stop Event;
never cancel active work to perform a URL update. State is local, temporary and public.
"""
import asyncio
import hashlib
import json
import os
import re
import sys
import time
from pathlib import Path

DIRECTORY = Path('/tmp/yeodam-runpod-control')
LEASE = DIRECTORY / 'lease.json'
STATE = DIRECTORY / 'state.json'
SOURCE = Path('/var/run/yeodam-vlm/base-url')
PROTOCOL = 1


def atomic(path, data):
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    temporary = path.with_suffix('.' + str(os.getpid()) + '.tmp')
    temporary.write_text(json.dumps(data))
    temporary.chmod(0o600)
    temporary.replace(path)


def lease():
    try:
        value = json.loads(LEASE.read_text())
        if re.fullmatch('[a-f0-9]{32}', value['operation']) and time.time() < value['expires'] <= time.time() + 3601:
            return value
    except (OSError, ValueError, KeyError, TypeError):
        pass
    return None


class Control:
    def __init__(self, expected):
        self.expected = expected
        self.loops = {}
        self.http = 0
        self.monitor_task = None

    async def monitor(self):
        while True:
            current = lease()
            if current:
                for stop, _ in self.loops.values():
                    stop.set()
            atomic(STATE, {'protocol': PROTOCOL, 'operation': current['operation'] if current else None,
                           'draining': bool(current), 'idle': bool(current) and len(self.loops) == self.expected
                           and all(done for _, done in self.loops.values()) and self.http == 0,
                           'loops': len(self.loops), 'activeHttp': self.http})
            await asyncio.sleep(.2)

    def start(self):
        if self.monitor_task is None:
            self.monitor_task = asyncio.create_task(self.monitor())

    def wrap(self, original):
        async def controlled(store, kind, stop=None):
            self.start()
            key = object()
            try:
                while stop is None or not stop.is_set():
                    local = asyncio.Event()
                    self.loops[key] = (local, bool(lease()))
                    while lease():
                        if stop is not None and stop.is_set():
                            return
                        await asyncio.sleep(.2)
                    local = asyncio.Event()
                    self.loops[key] = (local, False)
                    async def stop_parent():
                        while not local.is_set():
                            if lease() or (stop is not None and stop.is_set()):
                                local.set()
                            await asyncio.sleep(.1)
                    watch = asyncio.create_task(stop_parent())
                    try:
                        await original(store, kind, local)
                    finally:
                        watch.cancel()
                        await asyncio.gather(watch, return_exceptions=True)
                    self.loops[key] = (local, True)
                    if stop is not None and stop.is_set():
                        return
                    # Keep the supervisor alive while drained; Kubernetes must not
                    # restart it automatically before the update controller decides.
                    if not local.is_set():
                        raise RuntimeError('AI loop returned without a drain request')
            finally:
                self.loops.pop(key, None)
        return controlled

    def middleware(self, application):
        async def controlled(scope, receive, send):
            if scope['type'] != 'http' or scope.get('path') in {'/health', '/metrics'}:
                return await application(scope, receive, send)
            if lease():
                await send({'type': 'http.response.start', 'status': 503,
                            'headers': [(b'content-type', b'application/json'), (b'retry-after', b'30')]})
                return await send({'type': 'http.response.body', 'body': b'{"error":"model_maintenance"}'})
            self.http += 1
            try:
                await application(scope, receive, send)
            finally:
                self.http -= 1
        return controlled


def install(expected):
    from app.jobs import runner
    control = Control(expected)
    runner.runner_loop = control.wrap(runner.runner_loop)
    return control


def cli():
    action = sys.argv[1]
    if action == 'drain':
        operation, ttl = sys.argv[2], int(sys.argv[3])
        assert re.fullmatch('[a-f0-9]{32}', operation) and 30 <= ttl <= 3600
        current = lease()
        assert current is None or current['operation'] == operation
        atomic(LEASE, {'operation': operation, 'expires': time.time() + ttl})
        result = {'requested': True}
    elif action == 'resume':
        current = lease()
        if current:
            assert current['operation'] == sys.argv[2]
            LEASE.unlink()
        result = {'resumed': True}
    elif action == 'status':
        result = json.loads(STATE.read_text())
        current = lease()
        if not current or current['operation'] != result.get('operation'):
            result.update(idle=False, draining=False)
        else:
            result['leaseRemainingSeconds'] = int(current['expires'] - time.time())
    elif action == 'source':
        result = {'sourceMatches': hashlib.sha256(SOURCE.read_bytes().strip()).hexdigest() == sys.argv[2]}
    elif action == 'environment':
        result = {'environmentMatches': hashlib.sha256(os.environ['VLM_BASE_URL'].encode()).hexdigest() == sys.argv[2], 'modelMatches': os.environ['VLM_MODEL'] == 'gemma-4'}
    elif action == 'verify':
        import urllib.request
        url = os.environ['VLM_BASE_URL']
        assert hashlib.sha256(url.encode()).hexdigest() == sys.argv[2]
        assert re.fullmatch(r'https://[a-z0-9]+-8000\.proxy\.runpod\.net/v1', url)
        request = urllib.request.Request(url + '/models', headers={'Authorization': 'Bearer ' + os.environ['VLM_API_KEY']})
        # No redirects: never send the authorization to a different endpoint.
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args, **kwargs): return None
        with urllib.request.build_opener(NoRedirect()).open(request, timeout=20) as response:
            data = json.loads(response.read(1024 * 1024))
        result = {'environmentMatches': True,
                  'modelReady': any(x.get('id') == os.environ['VLM_MODEL'] for x in data.get('data', []))}
    else:
        raise ValueError('Unknown bounded control action')
    print(json.dumps(result))


if __name__ == '__main__':
    try:
        cli()
    except Exception:
        raise SystemExit('AI control failed; sensitive output suppressed') from None

templates/resources.yaml:
{{- $active := or .Values.workloads.api .Values.workloads.runner }}
{{- if $active }}
{{- if not (and .Values.accessEnabled .Values.review.sourceCompatible .Values.review.imageReviewed .Values.review.connectionsReviewed) }}{{ fail "Review compatible source, immutable image, Secret supply and shared model access before enabling AI" }}{{ end }}
{{- if not (regexMatch "^ghcr.io/100-hours-a-week/yeodam-ai-app@sha256:[a-f0-9]{64}$" .Values.image) }}{{ fail "Immutable AI app image required" }}{{ end }}
{{- if not (and (regexMatch "^[a-f0-9]{40}$" .Values.source) (regexMatch "^[a-f0-9]{64}$" .Values.configurationRevision)) }}{{ fail "Source and metadata revision required" }}{{ end }}
{{- end }}
{{- if .Values.accessEnabled }}
{{- range $key, $ca := .Values.trust }}{{ if not (contains "-----BEGIN CERTIFICATE-----" $ca) }}{{ fail "Public Redis/Qdrant/Kafka CA required" }}{{ end }}{{ end }}
{{- $c := .Files.Get "files/contract.json" | fromJson }}
---
apiVersion: v1
kind: ConfigMap
metadata: {name: ai-trust, namespace: ai}
data:
  redis.crt: {{ .Values.trust.redis | quote }}
  qdrant.crt: {{ .Values.trust.qdrant | quote }}
  kafka.crt: {{ .Values.trust.kafka | quote }}
---
apiVersion: v1
kind: ConfigMap
metadata: {name: ai-runtime-scripts, namespace: ai}
data:
{{ (.Files.Glob "files/runtime/*").AsConfig | indent 2 }}
---
apiVersion: external-secrets.io/v1
kind: ExternalSecret
metadata: {name: ai-runtime, namespace: ai}
spec:
  refreshPolicy: Periodic
  refreshInterval: 1h
  secretStoreRef: {kind: SecretStore, name: aws-secretsmanager}
  target: {name: ai-runtime, creationPolicy: Orphan, deletionPolicy: Retain, template: {type: Opaque}}
  data:
  {{- range $key := concat $c.secretKeys $c.runnerExtraSecrets }}
    - secretKey: {{ $key }}
      remoteRef: {key: yeodam/v3/foundation/ai/runtime, property: {{ $key }}, version: AWSCURRENT, decodingStrategy: None}
  {{- end }}
{{- range $role, $w := $c.workloads }}
---
apiVersion: v1
kind: ServiceAccount
metadata: {name: {{ $w.name }}, namespace: ai}
automountServiceAccountToken: false
---
apiVersion: v1
kind: ConfigMap
metadata: {name: {{ $w.name }}-runtime, namespace: ai}
data:
  RELEASE: {{ $.Values.source | quote }}
  {{- range $key, $value := $c.commonEnvironment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
  {{- range $key, $value := $w.environment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
{{- if index $.Values.workloads $role }}
---
apiVersion: apps/v1
kind: Deployment
metadata: {name: {{ $w.name }}, namespace: ai}
spec:
  replicas: 1
  revisionHistoryLimit: 2
  strategy: {type: Recreate}
  selector:
    matchLabels: {app.kubernetes.io/instance: {{ $w.name }}, yeodam.io/stage: v3}
  template:
    metadata:
      labels:
        app.kubernetes.io/name: ai
        app.kubernetes.io/instance: {{ $w.name }}
        app.kubernetes.io/component: {{ $role }}
        app.kubernetes.io/part-of: yeodam
        yeodam.io/stage: v3
        yeodam.io/ai-runtime: "true"
      annotations:
        checksum/runtime: {{ (printf "%s%s" ($.Files.Get "files/contract.json") (($.Files.Glob "files/runtime/*").AsConfig)) | sha256sum }}
        yeodam.io/configuration-revision: {{ $.Values.configurationRevision | quote }}
    spec:
      serviceAccountName: {{ $w.name }}
      automountServiceAccountToken: false
      imagePullSecrets: [{name: ghcr-pull}]
      nodeSelector: {yeodam.io/role: {{ $w.nodeRole }}, yeodam.io/stage: v3}
      tolerations: [{key: yeodam.io/role, operator: Equal, value: {{ $w.nodeRole }}, effect: NoSchedule}]
      terminationGracePeriodSeconds: {{ $w.grace }}
      securityContext:
        runAsNonRoot: true
        runAsUser: 10001
        runAsGroup: 10001
        fsGroup: 10001
        seccompProfile: {type: RuntimeDefault}
      initContainers:
        - name: prepare-trust
          image: {{ $.Values.image }}
          command: [python, /runtime/prepare-trust.py]
          resources: {requests: {cpu: 25m, memory: 32Mi}, limits: {memory: 64Mi}}
          securityContext: {allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: {drop: [ALL]}}
          volumeMounts:
            - {name: scripts, mountPath: /runtime, readOnly: true}
            - {name: public-ca, mountPath: /etc/yeodam/ca, readOnly: true}
            - {name: trust, mountPath: /etc/yeodam/trust}
      containers:
        - name: ai
          image: {{ $.Values.image }}
          command: {{ $w.command | toJson }}
          envFrom: [{configMapRef: {name: {{ $w.name }}-runtime}}]
          env:
          {{- $keys := $c.secretKeys }}
          {{- if eq $role "runner" }}{{ $keys = concat $keys $c.runnerExtraSecrets }}{{ end }}
          {{- range $key := $keys }}
            - name: {{ $key }}
              valueFrom: {secretKeyRef: {name: ai-runtime, key: {{ $key }}}}
          {{- end }}
          resources:
{{ $w.resources | toYaml | indent 12 }}
          securityContext: {allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: {drop: [ALL]}}
          {{- if eq $role "api" }}
          ports: [{name: http, containerPort: 8000}]
          startupProbe: {httpGet: {path: /health, port: http}, periodSeconds: 5, timeoutSeconds: 5, failureThreshold: 60}
          readinessProbe: {httpGet: {path: /health, port: http}, periodSeconds: 10, timeoutSeconds: 5, failureThreshold: 3}
          livenessProbe: {exec: {command: [python, /runtime/health.py, api-live]}, periodSeconds: 20, timeoutSeconds: 5, failureThreshold: 3}
          {{- else }}
          startupProbe: {exec: {command: [python, /runtime/health.py, runner-ready]}, periodSeconds: 10, timeoutSeconds: 5, failureThreshold: 180}
          readinessProbe: {exec: {command: [python, /runtime/health.py, runner-ready]}, periodSeconds: 15, timeoutSeconds: 5, failureThreshold: 3}
          {{- end }}
          volumeMounts:
            - {name: scripts, mountPath: /runtime, readOnly: true}
            - {name: public-ca, mountPath: /etc/yeodam/ca, readOnly: true}
            - {name: trust, mountPath: /etc/yeodam/trust, readOnly: true}
            - {name: tmp, mountPath: /tmp}
            - {name: model-url, mountPath: /var/run/yeodam-vlm, readOnly: true}
            {{- if eq $role "runner" }}
            - {name: reference, mountPath: /data/ai-reference}
            {{- end }}
      volumes:
        - {name: scripts, configMap: {name: ai-runtime-scripts, defaultMode: 0444}}
        - {name: public-ca, configMap: {name: ai-trust}}
        - {name: trust, emptyDir: {sizeLimit: 1Mi}}
        - {name: tmp, emptyDir: {sizeLimit: 256Mi}}
        - name: model-url
          secret:
            secretName: ai-runtime
            items: [{key: VLM_BASE_URL, path: base-url}]
        {{- if eq $role "runner" }}
        - {name: reference, emptyDir: {sizeLimit: 3Gi}}
        {{- end }}
{{- end }}
{{- end }}
{{- if .Values.workloads.api }}
---
apiVersion: v1
kind: Service
metadata: {name: ai-api, namespace: ai}
spec:
  type: ClusterIP
  selector: {app.kubernetes.io/instance: ai-api, yeodam.io/stage: v3}
  ports: [{name: http, port: 8000, targetPort: http}]
{{- end }}
{{- range $p := .Files.Get "files/policies.json" | fromJsonArray }}
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: {{ $p.name }}, namespace: {{ $p.namespace }}}
spec:
{{ $p.spec | toYaml | indent 2 }}
{{- end }}
{{- if .Values.privateModelPeers }}
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: allow-ai-reviewed-private-models, namespace: ai}
spec:
  podSelector:
    matchLabels: {yeodam.io/ai-runtime: "true", yeodam.io/stage: v3}
  policyTypes: [Egress]
  egress:
  {{- range $peer := .Values.privateModelPeers }}
    - to: [{ipBlock: {cidr: {{ $peer.cidr | quote }}}}]
      ports: [{protocol: TCP, port: {{ $peer.port }}}]
  {{- end }}
{{- end }}
{{- end }}
